<?php require __DIR__.'/partials/header.php';$symbols=array_values(array_filter(array_map(fn($x)=>strtoupper(trim($x)),explode(',',$_GET['symbols']??'AAPL,MSFT'))));$rows=[];foreach($symbols as $s){try{$rows[]=q('SELECT * FROM stocks WHERE symbol=?',[$s])->fetch()?:['symbol'=>$s];}catch(Throwable $x){}}?><section class="section-head"><div><span class="eyebrow">COMPARISON</span><h1>Compare companies</h1></div></section><form class="filterbar card"><label>Symbols<input name="symbols" value="<?=e(implode(',',$symbols))?>"></label><button class="primary">Compare</button></form><div class="table-card"><table><tr><th>Metric</th><?php foreach($rows as $r):?><th><?=e($r['symbol'])?></th><?php endforeach;?></tr><?php foreach(['market_cap'=>'Market cap','pe'=>'P/E','eps'=>'EPS','beta'=>'Beta','revenue_growth'=>'Revenue growth','eps_growth'=>'EPS growth'] as $k=>$label):?><tr><td><?=$label?></td><?php foreach($rows as $r):?><td><?=e($r[$k]??'—')?></td><?php endforeach;?></tr><?php endforeach;?></table></div><?php require __DIR__.'/partials/footer.php'; ?>